    ('{crop} on this farm: {cls} (score {score}/100).', '{crop} sur cette parcelle : {cls} (score {score}/100).', '{crop} في هذه الضيعة: {cls} (التقييم {score}/100).'),
    ('{crop} sown this month: {cls} (score {score}/100).', '{crop} semé ce mois-ci : {cls} (score {score}/100).', '{crop} إذا زُرع هذا الشهر: {cls} (التقييم {score}/100).'),
